window.NOTES={"version":70,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":14,"chapter":10,"section":"10.1","type":"单选","topic":"关系模型","title":"属性、域、候选码、主键与外键要分层判断","trigger":"题目要求辨认关系模型中属性取值范围、行和列的术语。","conclusion":"关系的一行称元组，一列对应属性，属性允许取值的集合称域；候选码还必须是能够唯一标识元组且不含多余属性的最小属性集合。","points":["先把学生关系看成有明确列含义的二维表：“01、王宁、女”整行是一个元组，“姓名”这一列是属性。若本例规定性别域为{男、女、未说明}，域就包含尚未在当前表中出现的“未说明”。关系模式描述名称、属性和约束，当前记录是关系实例。","超码能唯一标识元组；候选码是在超码中删去任何一个属性后都不再具有唯一标识能力的集合。这里的“最小”指没有冗余属性，不是所有候选码的属性数必须一样多。","从候选码中选一个作为主码；主码可以由多个属性联合构成。一张表至多声明一个主键，但这个主键可以包含多列。","例如选课关系可用“学号、课程号”共同标识一条选课；学号单独出现多次，不代表联合主键有重复。","SQL主键约束要求唯一且非空；普通UNIQUE约束对NULL的处理依数据库及设置而异，不能直接当成主键。","外键用于参照完整性，本列通常可以重复；它引用主键或受支持的唯一键，是否允许空值还取决于非空约束等设置。","候选码要由业务规则保证唯一，不能因为眼前几行姓名恰好没有重复，就断言姓名能永久作为候选码。","关系模型中的关系是元组的集合，行的先后顺序不承担唯一标识作用，完全相同的元组不重复出现；SQL表若未设置相应约束则可能存有重复行。不能仅因画成二维表，就忽略关系的模型约束。","先分清管理对象：数据可以是姓名、日期、分数等事实的记录，不只指数字。数据库DB是按一定结构组织、长期存储、可被管理使用的数据集合；数据库管理系统DBMS是定义和管理这些数据的软件。数据库系统DBS还包括应用、人员及运行环境，完整组成在10.2展开。","数据模型说明怎样组织数据、允许哪些操作及满足什么约束。经典层次模型用树形联系组织记录，网状模型允许一个记录有多个上级联系，关系模型用关系及其运算和完整性规则组织数据；它们不是三种文件扩展名。","关系可用二维表表示，但不是任意电子表格都自动构成关系数据库。“姓名”是属性名，“王宁”是某个属性值；一条学生记录是一行。Excel可存放这样的行列数据，但不因此成为负责关系、权限和参照完整性管理的DBMS。","完整性约束把业务规则变成数据检查：实体完整性要求主键各部分不能为NULL，主键还必须唯一；参照完整性检查外键引用是否合法；用户定义完整性表达具体限制，如成绩非空且在0到100之间。符合这些规则不等于用户有权访问，权限是另一层控制。","例：班级表的班级号有A、B，学生表的单列外键班级号可重复引用A。写入不存在的Z违反参照完整性；若该外键允许NULL，尚未分班可以存NULL，若同时要求非空则不行。外键可由多列组成，也可参照本表支持的目标键；删除被引用班级时是阻止、级联还是置空，须看声明的策略。"],"boundary":"域不是某一行或当前列中已经出现的值；候选码不只是“能唯一”的任意属性集合，也不是只能含一列。“字段/记录”与“属性/元组”应按表和关系模型语境区分。","id":"y2023q14","sources":[{"year":2023,"q":14,"type":"单选"}],"keys":["2023-14"],"comparison":{"headers":["概念","判断依据"],"rows":[["域","该属性允许出现哪些值"],["超码","能否唯一标识元组"],["候选码","唯一标识且不存在多余属性"],["主码","从候选码中选定，SQL约束要求唯一且非空"],["外键","非空引用值是否对应合法的被引用键"]]},"pointGroups":[{"title":"从数据和模型进入关系","indices":[8,9,10,0,7]},{"title":"唯一标识：候选码和主键","indices":[1,2,3,4,6]},{"title":"引用关系与完整性","indices":[5,11,12]}],"related":[{"id":"y2020q14","label":"一对一、一对多和多对多联系要双向判断","reason":"一对多常在多端保存外键，多对多常用关联表；联合主键是否重复要看整组属性。"},{"id":"y2025q12","label":"INSERT向表中添加新记录","reason":"插入新记录时，主键、非空、唯一和外键约束都会检查，定义正确不代表任意值都可写入。"},{"id":"y2024q36","label":"DELETE删除满足条件的记录，不删除表结构","reason":"外键与其他约束也可能限制删除或触发级联，DELETE的作用不能只由WHERE单独推断。"}],"pointPresentation":{"0":{"title":"元组、属性与域","navigationLabel":"元组、属性与域"},"1":{"title":"超码与最小候选码","navigationLabel":"超码与最小候选码"},"2":{"title":"主键可由多列组成","navigationLabel":"主键可由多列组成"},"3":{"title":"联合主键看整组","navigationLabel":"联合主键看整组"},"4":{"title":"PRIMARY KEY与UNIQUE","navigationLabel":"PRIMARY KEY与UNIQUE"},"5":{"title":"外键的引用条件","navigationLabel":"外键的引用条件"},"6":{"title":"业务规则与当前样本","navigationLabel":"业务规则与当前样本"},"7":{"title":"关系集合与SQL重复","navigationLabel":"关系集合与SQL重复"},"8":{"title":"数据、数据库与管理软件","navigationLabel":"数据、数据库与管理软件"},"9":{"title":"经典数据模型","navigationLabel":"经典数据模型"},"10":{"title":"二维外观不等于DBMS","navigationLabel":"二维外观不等于DBMS"},"11":{"title":"三类完整性与访问权限","navigationLabel":"三类完整性与访问权限"},"12":{"title":"外键NULL、自参照和删除策略","navigationLabel":"外键NULL、自参照和删除策略"}},"searchAliases":["数据库基础 DB DBMS DBS","实体完整性 参照完整性 用户定义完整性","主码 外码 外键 NULL"]},{"q":25,"chapter":10,"section":"10.1","type":"多选","topic":"关系运算","title":"选择、投影、连接与集合运算","trigger":"真题从WHERE对应、单表取行列、多表组合和“只属于一个集合”考查关系代数。","conclusion":"选择筛选行，投影取得列并按关系代数的集合语义去重，连接按匹配条件组合元组；并、交、差还要检查两侧关系是否相容。","points":["从人员表筛出男性使用选择，再只保留编号、姓名、性别使用投影；若需要全部人员的指定字段，不必额外增加行条件。","关系代数的结果仍是集合，所以投影会消除重复元组。例如班级列为A、B、A，投影班级只得到A、B；普通SQL SELECT默认可保留重复行，SELECT DISTINCT才去重。","自然连接按全部同名属性相等匹配，公共属性在输出中只保留一列；自然内连接不保留未匹配行。若两表同名列有“学号、班级”，(01,A)不能匹配(01,B)，只让学号相等还不够。","连接不是按两表的显示行号一一拼接；同一个连接值若匹配多行，应产生所有匹配组合。要按指定字段连接时，应明确连接条件。","并、交、差要求两侧列数相同且对应列的域或数据类型相容；字段名或顺序不一致时要先明确对应关系，不能把任意两张表直接做集合运算。","S−T只保留属于S而不属于T的元组，方向不能颠倒；“仅属于两集合之一”是(S−T)∪(T−S)，不是单独的S−T。","跨表获取相关信息通常可理解为先连接，再按目标选择行、投影列；这是语义分析方式，不是强制数据库按同一物理顺序执行。","笛卡儿积（也称笛卡尔积）把两关系的每个元组两两组合；两侧分别有m、n行时得到m×n种组合。2020年第25题只需在同一学生表选择女同学的行，再投影姓名列，无需连接或笛卡儿积。","并S∪T保留至少在一侧出现的元组，交S∩T保留两侧都有的元组，差S−T只保留S有而T没有的元组。例如两侧都是“学号”这一列，S={01,02}、T={02,03}，则并为{01,02,03}、交为{02}、S−T为{01}。这些结果按集合去重；若两侧列数或对应域不相容，不能直接套这个例子。","跨表变式（2026年第11题）：性别在学生关系中，计算机成绩在成绩关系中。先按性别选出女生，再按学号连接对应成绩，最后投影学号、姓名和计算机成绩三列；三种运算各有必要。取消女生限制可省选择，只查姓名且不用成绩可省连接。这里说明语义关系，不规定DBMS的物理执行顺序。"],"boundary":"关系代数的“选择”对应筛行，不等于SQL命令名SELECT的全部作用；投影去重、集合相容性和连接匹配条件都不能省略。","id":"merged-20","sources":[{"year":2020,"q":25,"type":"多选"},{"year":2023,"q":46,"type":"填空"},{"year":2024,"q":14,"type":"单选"},{"year":2026,"q":11,"type":"单选"},{"year":2022,"q":27,"type":"多选"},{"year":2021,"q":13,"type":"单选","page":3}],"keys":["2020-25","2023-46","2024-14","2026-11","2022-27","2021-13"],"comparison":{"headers":["运算","主要改变","易错边界"],"rows":[["选择σ","保留满足条件的行","列结构不因此减少"],["投影π","保留指定列","关系代数结果去重"],["自然连接⋈","组合所有同名属性相等的元组","不是按显示行号拼接"],["差S−T","保留S有而T没有的元组","有方向且要求关系相容"],["笛卡儿积×","两侧元组的全部组合","m行与n行得到m×n行，不附加匹配条件"]]},"pointGroups":[{"title":"行、列与跨表匹配","indices":[0,1,2,3]},{"title":"集合运算与组合使用","indices":[4,8,5,7,6,9]}],"related":[{"id":"merged-21","label":"SELECT查询与字段选择","reason":"把筛行、取列映射到WHERE和SELECT，同时注意关系代数投影去重与SQL默认保留重复的差别。"},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"理解连接匹配和结果重复前，先分清属性、主键、外键及某列是否由业务规则保证唯一。"},{"id":"y2020q14","label":"一对一、一对多和多对多联系要双向判断","reason":"一对多、多对多联系决定跨表匹配的可能数量，连接不能按屏幕行号机械拼接。"}],"workedExamples":[{"year":2024,"q":14,"questionSummary":"从两个报名集合中找只参加第一项的学生。","reasoning":["S代表第一项报名，T代表第二项报名；目标要求同时满足属于S与不属于T。","因此用差集S−T；两关系属性相同，满足本题集合运算的相容前提。","交集是两项都参加，并集是至少一项参加，T−S会把方向倒过来。"],"pitfall":"把“只参加100米”看成两项都参加，或把差集方向颠倒。","transfer":"如果改问只参加其中一项，应取(S−T)∪(T−S)，不是单独一个差集。","sourceURL":"https://www.aipta.com/article/10360.html","sourceStatus":"v69已读取原卷扫描及配套答案；配套答案未取得官方发布依据","historicalVersionNote":""},{"year":2020,"q":25,"questionSummary":"从学生表中取得女同学姓名，判断需要的关系运算。","reasoning":["先按性别条件取符合的行，这是选择。","再只保留姓名这一属性，这是投影。","所需字段都在同一关系中，无需额外连接或做笛卡儿积。"],"pitfall":"把SQL关键词SELECT直译成关系代数中的单一“选择”，忽略取列还涉及投影。","transfer":"改成查询全部学生姓名时只需投影；改成跨两表取得课程成绩时再考虑连接。","sourceURL":"https://www.sohu.com/a/422753629_100179611","sourceStatus":"v69已读取原卷扫描及配套答案；配套答案未取得官方发布依据","historicalVersionNote":""}],"pointPresentation":{"0":{"title":"选择行与投影列","navigationLabel":"选择行与投影列"},"1":{"title":"关系投影与SQL去重","navigationLabel":"关系投影与SQL去重"},"2":{"title":"自然连接的公共属性","navigationLabel":"自然连接的公共属性"},"3":{"title":"所有匹配组合","navigationLabel":"所有匹配组合"},"4":{"title":"集合相容性","navigationLabel":"集合相容性"},"5":{"title":"差集方向与只参加一项","navigationLabel":"差集方向与只参加一项"},"6":{"title":"组合运算的语义次序","navigationLabel":"组合运算的语义次序"},"7":{"title":"笛卡儿积与结果数量","navigationLabel":"笛卡儿积与结果数量"},"8":{"title":"并、交、差完整小例","navigationLabel":"并、交、差完整小例"},"9":{"title":"跨表查询的三种必要运算","navigationLabel":"跨表查询的三种必要运算"}}},{"q":35,"chapter":10,"section":"10.1","type":"填空","topic":"SQL查询","title":"SELECT查询与字段选择","trigger":"两道题分别考查SQL查询命令和星号的含义。","conclusion":"SELECT指定结果列，FROM指定数据来源，WHERE筛选行，ORDER BY规定输出顺序；星号只代表来源中的全部列，不能据此断定全部行都会返回。","points":["基本结构可写为SELECT 字段 FROM 表 WHERE 条件 ORDER BY 字段；是否返回某行还取决于WHERE、连接及其他查询条件。","SELECT默认可能保留重复结果；需要去重时使用DISTINCT。GROUP BY用于分组，不应拿它代替单纯的去重或排序说明。","没有ORDER BY时，不保证按插入顺序、主键顺序或屏幕上原来的顺序返回。排序值相同且需要固定次序时，可追加学号等排序键。","WHERE只保留条件为真的行；NULL表示未知或缺失，判断它应写IS NULL或IS NOT NULL，不能用“= NULL”判断是否为空；通常这种比较得到未知，而不是语法错误。","例如SELECT 姓名 FROM 学生 WHERE 成绩 &gt;= 60只返回达标学生姓名；成绩为NULL不自动等于0，也不会使该比较条件成立。","实际应用宜明确列出所需字段，减少无用传输并稳定结果结构；ORDER BY排列查询结果，不修改源表数据。","完整小例：students有(1,王宁,88)、(2,李明,56)、(3,赵敏,92)、(4,周林,NULL)，列为id、name、score。执行SELECT name, score FROM students WHERE score >= 60 ORDER BY score DESC;，先保留88和92这两行，再输出姓名与成绩，按降序得到(赵敏,92)、(王宁,88)；原表四行不变。","SQL不只有查询：CREATE、ALTER、DROP针对对象定义，INSERT、UPDATE、DELETE针对数据行，SELECT产生查询结果。本章按作用对象区分；不同教材对SELECT单列DQL还是归入数据操纵有分类差异，不凭缩写替代命令语义。"],"boundary":"SELECT *的星号表示所有列，不是所有行；NULL不是0或空字符串，结果排序也不等于更新源数据。","id":"merged-21","sources":[{"year":2020,"q":35,"type":"填空"},{"year":2026,"q":43,"type":"填空"}],"keys":["2020-35","2026-43"],"comparison":{"headers":["语句部分","作用"],"rows":[["SELECT 姓名,成绩","决定返回哪些列"],["WHERE 成绩 >= 60","决定保留哪些行"],["SELECT DISTINCT 性别","去除结果中的重复行"],["ORDER BY 成绩 DESC,学号 ASC","决定结果次序及同分时的次序"],["成绩 IS NULL","查找缺失成绩"]]},"related":[{"id":"merged-20","label":"选择、投影、连接与集合运算","reason":"用关系代数区分选择行、投影列和连接来源，解释SELECT命令并不只对应其中的选择运算。"},{"id":"y2023q15","label":"UPDATE修改已有记录中的字段值","reason":"UPDATE前可用相同WHERE查询核对目标行，查询条件的理解直接决定修改范围。"},{"id":"y2020q9","label":"高级筛选同一行是AND，不同行是OR","reason":"SQL筛行和Excel高级筛选都要求正确组合条件，同行AND、异行OR可帮助练习条件分组。"}],"pointGroups":[{"title":"确定来源、筛选行并处理NULL","indices":[0,3,4]},{"title":"组织结果列、去重与排序","indices":[1,2,5,6]},{"title":"放回SQL的操作层级","indices":[7]}],"pointPresentation":{"0":{"title":"SELECT、FROM与WHERE","navigationLabel":"SELECT、FROM与WHERE"},"1":{"title":"默认重复与DISTINCT","navigationLabel":"默认重复与DISTINCT"},"2":{"title":"ORDER BY与稳定次序","navigationLabel":"ORDER BY与稳定次序"},"3":{"title":"NULL比较与IS NULL","navigationLabel":"NULL比较与IS NULL"},"4":{"title":"达标查询的行列边界","navigationLabel":"达标查询的行列边界"},"5":{"title":"结果排序不改源表","navigationLabel":"结果排序不改源表"},"6":{"title":"查询的完整输入与结果","navigationLabel":"查询的完整输入与结果"},"7":{"title":"SQL按操作对象分层","navigationLabel":"SQL按操作对象分层"}},"searchAliases":["SQL查询 空值 IS NULL DISTINCT","DQL DDL DML"]},{"q":47,"chapter":10,"section":"10.1","type":"填空","topic":"SQL表结构","title":"ALTER TABLE用于修改已有表结构","trigger":"题目要求向已有数据表添加年龄字段。","conclusion":"可使用ALTER TABLE 表名 ADD 年龄 数据类型，向表中增加字段；具体数据类型和关键字细节由DBMS决定。","points":["ALTER修改数据库对象结构。","INSERT新增记录，UPDATE修改记录值。","添加非空字段时还要考虑已有记录的默认值。","CREATE TABLE创建表，ALTER TABLE修改表结构，DROP TABLE移除表；UPDATE修改已有记录的字段值，DELETE删除记录，层次不同。","先建表再存记录。例如CREATE TABLE students (id INTEGER PRIMARY KEY, name VARCHAR(20) NOT NULL, score INTEGER); 定义三个字段及其约束，成功后得到空表，不会自动生成学生记录。id表示整数标识且为主键，name最多20个字符且非空；score在此例允许NULL。","列定义由列名、数据类型和必要约束组成。INTEGER适合整数，VARCHAR(n)表示有长度上限的可变长字符串；带前导0且不用于计算的编号可选择字符类型。类型限制可存什么值，主键、非空、外键等约束再表达具体规则；不同DBMS的类型范围和转换细节需另核。","增加年龄列可采用ALTER TABLE students ADD age INTEGER; 这一常见写法；一些DBMS还接受ADD COLUMN。修改列类型或删除列的语法与限制也有差异，应查目标DBMS。本章综合沙箱的ADD COLUMN remark TEXT采用PostgreSQL兼容写法，不是要求所有数据库使用TEXT或COLUMN。"],"boundary":"改表结构可能锁表或影响应用，生产环境应先评估兼容性、备份和迁移方案。","id":"y2024q47","sources":[{"year":2024,"q":47,"type":"填空"},{"year":2021,"q":35,"type":"填空","page":6}],"keys":["2024-47","2021-35"],"related":[{"id":"y2025q12","label":"INSERT向表中添加新记录","reason":"给表增加字段使用ALTER，给表增加记录使用INSERT，可用列与行的变化辨认命令。"},{"id":"y2024q36","label":"DELETE删除满足条件的记录，不删除表结构","reason":"进一步比较删记录、清空记录、调整字段与移除表对象，避免把结构变化当作DELETE。"},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"新增非空、主键或外键等约束前，要检查已有数据是否符合这些约束所表达的业务规则。"}],"pointGroups":[{"title":"先定义一张表","indices":[4,5,3]},{"title":"再修改已有结构","indices":[0,6,2,1]}],"pointPresentation":{"0":{"title":"ALTER修改表定义","navigationLabel":"ALTER修改表定义"},"1":{"title":"增行和改值不等于增列","navigationLabel":"增行和改值不等于增列"},"2":{"title":"已有数据与新增约束","navigationLabel":"已有数据与新增约束"},"3":{"title":"CREATE、ALTER、DROP","navigationLabel":"CREATE、ALTER、DROP"},"4":{"title":"CREATE TABLE得到空表","navigationLabel":"CREATE TABLE得到空表"},"5":{"title":"列名、类型与约束","navigationLabel":"列名、类型与约束"},"6":{"title":"ADD COLUMN与产品方言","navigationLabel":"ADD COLUMN与产品方言"}},"searchAliases":["CREATE TABLE 建表 数据类型 VARCHAR INTEGER","DROP TABLE 表结构"]},{"q":12,"chapter":10,"section":"10.1","type":"单选","topic":"SQL写入","title":"INSERT向表中添加新记录","trigger":"题目要求选择把新生记录加入信息表的SQL命令。","conclusion":"INSERT用于插入新记录；SELECT查询，DELETE删除记录，ALTER修改数据库对象结构。","points":["常见形式是INSERT INTO 表名(字段) VALUES(值)。","字段与值的数量、顺序和数据类型应对应。","主键、非空、唯一和外键约束仍会检查新记录。","承接students(id, name, score)建表例，INSERT INTO students (id, name, score) VALUES (5, '陈晨', 75); 增加一条记录。三项值按列列表对应，而不是按值的含义猜位置；调换列列表时也须对应调换值。若id=5已存在，再执行会违反本例主键约束，不是把原记录覆盖为75分。"],"boundary":"ALTER用于改表结构，不用于把普通记录追加到表中。","id":"y2025q12","sources":[{"year":2025,"q":12,"type":"单选"}],"keys":["2025-12"],"related":[{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"字段与值对应正确后，还须满足主键唯一非空及外键参照等条件，才能成功新增记录。"},{"id":"y2023q15","label":"UPDATE修改已有记录中的字段值","reason":"新增记录用INSERT，修改已存在记录用UPDATE；是否已经有目标行决定操作选择。"},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"INSERT增加行而不增加字段，补充字段定义要修改表结构。"}],"pointGroups":[{"title":"先判断新增记录的对象","indices":[0,3]},{"title":"再检查列值和约束","indices":[1,2]}],"pointPresentation":{"0":{"title":"INSERT增加新行","navigationLabel":"INSERT增加新行"},"1":{"title":"列列表和值的对应","navigationLabel":"列列表和值的对应"},"2":{"title":"插入也要满足约束","navigationLabel":"插入也要满足约束"},"3":{"title":"完整插入例与重复主键","navigationLabel":"完整插入例与重复主键"}}},{"q":15,"chapter":10,"section":"10.1","type":"单选","topic":"SQL更新","title":"UPDATE修改已有记录中的字段值","trigger":"题目要求选择用于修改关系表中已有数据的SQL命令。","conclusion":"UPDATE用于更新已有记录；SET指定新值，WHERE限定被修改的记录。","points":["基本形式为UPDATE 表名 SET 字段=值 WHERE 条件。例如UPDATE 学生 SET 成绩=成绩+5 WHERE 学号='01'，表示先找到学号01的记录，再把原成绩加5写回；原来65会变为70。","WHERE控制修改哪些行，SET控制这些行中的哪些列。省略WHERE通常针对全部记录；条件一行也未命中时可修改0行，未列在SET中的普通字段保持原值。","INSERT添加记录，DELETE删除记录，ALTER修改表结构。"],"boundary":"执行更新前应先用相同WHERE条件查询核对；UPDATE改数据，不负责修改字段结构。","id":"y2023q15","sources":[{"year":2023,"q":15,"type":"单选"}],"keys":["2023-15"],"related":[{"id":"merged-21","label":"SELECT查询与字段选择","reason":"先用同一WHERE查询目标行，再理解UPDATE将修改哪些已有记录；查询结果排序不会改变源值。"},{"id":"y2025q12","label":"INSERT向表中添加新记录","reason":"UPDATE改已有行中的值，INSERT添加新行，可用同一业务场景判断应修改还是追加。"},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"字段值改变用UPDATE，字段定义或约束改变用ALTER TABLE，须先判断操作的数据层级。"}],"pointGroups":null},{"q":36,"chapter":10,"section":"10.1","type":"判断","topic":"SQL删除","title":"DELETE删除满足条件的记录，不删除表结构","trigger":"题目解释DELETE FROM student WHERE 班级=\"一班\"的作用。","conclusion":"DELETE FROM student WHERE 班级=&#39;一班&#39;删除符合条件的记录并保留表结构；省略WHERE会针对全部行，DROP TABLE才移除整个表对象。","points":["WHERE决定DELETE或UPDATE的作用行；条件没有命中时可影响0行，这本身不表示语法错误。","DELETE FROM student执行后，即使没有剩余记录，student的字段和表对象仍存在；DROP TABLE student后，再查询该表应报告表不存在。","UPDATE用SET改已有记录的字段值；INSERT增加记录；ALTER TABLE改变字段、约束等结构，不能把删列当成DELETE。","ALTER TABLE新增字段时，已有记录该字段的取值由默认值、约束及DBMS规则共同决定。本卡示例增加可空列且未声明默认值，旧记录的新字段为NULL；不能把某一产品的默认值回填行为推广到所有DBMS。增加非空字段时须先确认已有数据能否满足约束。","TRUNCATE清空整表并保留表对象，但支持情况、触发器和事务行为依DBMS而异；不能背成“所有数据库中都不可回滚”，例如PostgreSQL的TRUNCATE可随事务回滚。","真正执行仍受权限、外键约束和触发器等限制；某些删除可能被拒绝或触发级联，不能用命令名称保证它一定成功。"],"boundary":"字符串通常用单引号，规范示例写WHERE 班级=&#39;一班&#39;；删行、改值、增删字段与删整表是不同层级，执行前应核对对象和条件。","id":"y2024q36","sources":[{"year":2024,"q":36,"type":"判断"},{"year":2022,"q":46,"type":"填空"}],"keys":["2024-36","2022-46"],"comparison":{"headers":["命令","主要对象","典型结果"],"rows":[["SELECT","查询结果","读取数据"],["INSERT","新记录","行数增加，仍检查约束"],["UPDATE…SET…WHERE…","命中的已有记录","字段值改变"],["DELETE…WHERE…","命中的已有记录","行移除，表结构保留"],["ALTER TABLE","表定义","增加、移除或修改字段及约束"],["DROP TABLE","整个表对象","表及其数据不再存在"]]},"related":[{"id":"y2023q15","label":"UPDATE修改已有记录中的字段值","reason":"DELETE和UPDATE都用WHERE限定作用行，但前者移除记录，后者通过SET修改字段值。"},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"删行、删列与删表对象属于不同层级，ALTER TABLE修改结构，DROP TABLE移除表。"},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"参照完整性可限制记录删除；主外键关系解释了为何有些DELETE会失败或发生级联。"}],"pointGroups":[{"title":"用条件确定作用行并区分操作层级","indices":[0,1,2]},{"title":"结构变化、整表清空与执行约束","indices":[3,4,5]}]},{"q":13,"chapter":10,"section":"10.2","type":"单选","topic":"数据库系统","title":"数据库、DBMS与数据库系统不是同一层级","trigger":"真题从Access、DBA、系统构成和核心软件关系考查数据库基本概念。","conclusion":"数据库是数据集合，DBMS是管理数据库的核心软件，数据库系统还包括应用、人员和运行环境；Access属于关系DBMS。","points":["DBMS负责定义、存取、控制、恢复和并发管理等。","DBA负责权限、备份恢复、性能与可用性。","数据库系统比文件系统提供更强的数据共享和一致性管理。","DB是Database（数据库），DBMS是Database Management System（数据库管理系统），DBS是Database System（数据库系统）。例如学生和选课数据构成数据库，Access或SQL Server等负责管理数据，教务应用、管理和使用人员以及硬件与操作系统环境共同构成数据库系统。DBA是人员，不是DBMS软件的另一名称。","数据管理常按三个阶段理解：人工管理阶段由应用程序自行安排数据管理，数据依赖程序且复用困难；文件系统阶段由操作系统管理文件，但各应用仍常保留自己的格式和数据副本；数据库系统阶段由DBMS统一组织、控制和共享数据。它们是在管理职责和共享能力上的发展，不是说文件系统完全不能共享或数据库没有冗余。","数据定义规定表、列和约束，数据操纵负责查询、插入、更新和删除；DBMS还组织存储与存取，并保存描述表结构、约束等的元数据。用户发出SQL请求，DBMS检查和处理后返回结果；SQL语言、DBMS软件与保存的数据不能互换。","运行控制有不同目标：权限检查决定谁能访问什么，完整性检查限制不合法数据，并发控制协调同时操作，备份与恢复应对故障。数据库系统可以支持这些机制，但正确配置、应用设计与人员操作仍有责任，安装DBMS不会自动保证一切安全。","数据独立性可用来理解程序与数据管理的分离：物理独立性指存储位置或存取组织改变时，尽量保持逻辑结构和应用接口；逻辑独立性指逻辑结构改变时，通过相应映射尽量保持用户视图和应用。它不意味着任意删除字段都无需修改程序；这里用于理解基本概念，不展开多级模式设计。","常见关系DBMS包括Access、SQL Server、Oracle Database、MySQL和PostgreSQL；它们的界面与SQL方言并不完全相同。Excel是电子表格软件，SQL是语言，DBA是人员，都不能与这些管理软件放在同一层分类。"],"boundary":"DB、DBMS和DBS不能互换；应说DBMS是数据库系统的核心软件，而不是反过来。","id":"y2020q13","sources":[{"year":2020,"q":13,"type":"单选"},{"year":2023,"q":36,"type":"判断"},{"year":2024,"q":27,"type":"多选"}],"keys":["2020-13","2023-36","2024-27"],"related":[{"id":"y2025q42","label":"数据库运维工作由数据库管理员负责","reason":"DBMS是管理软件，DBA是负责配置、安全和运维的人员，二者名称相近但层级不同。"},{"id":"merged-2","label":"系统软件与应用软件按功能区分","reason":"软件按主要功能分类，不能因名称含系统或随系统附带就判断其类别；DBMS也要按管理职责理解。"},{"id":"y2025q11","label":"数据库设计不因规模小而省略","reason":"拥有DBMS不等于已完成数据库设计，还须经过需求、概念、逻辑和物理设计。"}],"pointGroups":[{"title":"数据集合、管理软件与整个系统","indices":[3,8]},{"title":"管理功能和人员职责","indices":[5,0,6,1]},{"title":"发展过程与独立性","indices":[4,2,7]}],"pointPresentation":{"0":{"title":"DBMS的主要职责","navigationLabel":"DBMS的主要职责"},"1":{"title":"DBA的运维职责","navigationLabel":"DBA的运维职责"},"2":{"title":"数据库系统的数据共享","navigationLabel":"数据库系统的数据共享"},"3":{"title":"DB、DBMS、DBS与组成","navigationLabel":"DB、DBMS、DBS与组成"},"4":{"title":"数据管理三个阶段","navigationLabel":"数据管理三个阶段"},"5":{"title":"定义、操纵和元数据","navigationLabel":"定义、操纵和元数据"},"6":{"title":"权限、完整性、并发与恢复","navigationLabel":"权限、完整性、并发与恢复"},"7":{"title":"逻辑和物理独立性的边界","navigationLabel":"逻辑和物理独立性的边界"},"8":{"title":"常见DBMS与易混对象","navigationLabel":"常见DBMS与易混对象"}},"searchAliases":["数据库系统组成 DBS","人工管理 文件系统 数据库系统","数据独立性 数据字典 元数据"]},{"q":42,"chapter":10,"section":"10.2","type":"填空","topic":"数据库人员","title":"数据库运维工作由数据库管理员负责","trigger":"题目在数据库管理人员分类中判断负责数据库运维的角色。","conclusion":"数据库管理员DBA负责数据库安装配置、权限、安全、备份恢复、性能监控和日常运行维护。","points":["系统分析员侧重需求与系统方案。","应用程序员负责开发访问数据库的业务程序。","DBA还需管理账户、容量、日志和故障恢复。"],"boundary":"DBA不是所有数据内容的业务负责人，权限与职责仍应分离。","id":"y2025q42","sources":[{"year":2025,"q":42,"type":"填空"}],"keys":["2025-42"],"related":[{"id":"y2020q13","label":"数据库、DBMS与数据库系统不是同一层级","reason":"在数据库系统组成中定位DBA与DBMS，区分人员责任、核心管理软件和数据集合。"},{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"备份恢复、监控和故障处理服务于可用性等安全目标，能据题干后果辨认运维重点。"}]},{"q":14,"chapter":10,"section":"10.3","type":"单选","topic":"实体联系","title":"一对一、一对多和多对多联系要双向判断","trigger":"题目描述一个团支部有多名团员，而一个团员只属于一个团支部。","conclusion":"联系基数由业务规则决定：从两端分别判断一个实例最多可对应几个实例，再区分一对一、一对多与多对多。","points":["一对一表示双方每个实体最多对应另一方一个实体。","一对多常在“多”端保存“一”端的主键作外键。例如每名学生只属于一个班级，而一班可有多名学生：学生表保存班级号，多名学生的班级号可相同。","多对多通常用关联表拆成两个一对多。例如学生可选多门课、每门课可被多人选：选课表的一行记录一名学生与一门课程，分别用学号、课程号参照学生表和课程表。","判断联系必须双向看：一家出版社可向多家书店供书，一家书店也可向多家出版社进货，因此是多对多。具体基数取决于业务规则。","E-R模型先描述业务对象：一个具体学生是实体，相同类型学生组成实体集，学号、姓名等描述实体的属性，“学生选课程”是实体间的联系。常见教材画法用矩形表示实体型、椭圆表示属性、菱形表示联系；不同建模工具可有不同记法，先读题目约定。","转为关系模型时，一个实体型通常对应一张表，一个实体实例通常对应一行，属性对应列；联系再按基数落实为外键或关联表。E-R中的“联系”是业务关联，关系模型的“关系”是元组集合，不应因中文相近把二者混同。"],"boundary":"关系方向会影响措辞，但不会改变结构本质；判断时分别看两端最大对应数量。","id":"y2020q14","sources":[{"year":2020,"q":14,"type":"单选"},{"year":2022,"q":13,"type":"单选"}],"keys":["2020-14","2022-13"],"related":[{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"把业务联系落到表结构时，一对多使用外键、多对多使用关联表，需同时检查键的唯一性与空值规则。"},{"id":"y2025q11","label":"数据库设计不因规模小而省略","reason":"先在概念设计中表达实体联系，再在逻辑设计中形成关系模式，联系基数不能由当前样本随意决定。"},{"id":"merged-20","label":"选择、投影、连接与集合运算","reason":"连接必须产生所有符合条件的匹配组合，一对多或多对多会影响输出行数。"}],"pointGroups":[{"title":"先识别实体、属性和联系","indices":[4]},{"title":"双向判断联系数量","indices":[0,1,2,3]},{"title":"从业务联系形成关系表","indices":[5]}],"workedExamples":[{"year":2020,"q":14,"questionSummary":"由团支部与团员的双向业务约束判断联系类型。","reasoning":["固定一个团支部，可以找到多名团员。","固定一名团员，题设只允许归属一个团支部。","按“团支部→团员”的方向是1对多；联系类型须连同提问方向一起读。"],"pitfall":"只看“多人”而不做反向检查，或把题目实体顺序倒置。","transfer":"判断教师与课程等新情境时不能套常识，要先问一个A对应几个B，再问一个B对应几个A。","sourceURL":"https://www.sohu.com/a/422753629_100179611","sourceStatus":"v69已读取原卷扫描及配套答案；配套答案未取得官方发布依据","historicalVersionNote":""}],"pointPresentation":{"0":{"title":"一对一的双向限制","navigationLabel":"一对一的双向限制"},"1":{"title":"一对多和N端外键","navigationLabel":"一对多和N端外键"},"2":{"title":"多对多与关联表","navigationLabel":"多对多与关联表"},"3":{"title":"双向判断的业务条件","navigationLabel":"双向判断的业务条件"},"4":{"title":"E-R基本对象和教材图形","navigationLabel":"E-R基本对象和教材图形"},"5":{"title":"实体实例、表和关联的区别","navigationLabel":"实体实例、表和关联的区别"}},"searchAliases":["实体集 实体型 ER E-R 概念模型","关系基数 联系基数"]},{"q":11,"chapter":10,"section":"10.3","type":"单选","topic":"数据库设计","title":"数据库设计不因规模小而省略","trigger":"题目要求找出数据库设计阶段描述中的错误项。","conclusion":"数据库设计通常包括需求分析、概念结构、逻辑结构和物理结构等阶段，小型数据库同样需要与规模相称的设计。","points":["需求分析先问清业务要保存什么、要完成什么操作、有哪些限制，例如是否允许学生重复选同一门课；这些规则决定后续模型。","概念结构设计用E-R模型表示实体、属性和联系，例如“学生—选课—课程”；此时重在表达业务，通常不依赖具体DBMS。","物理结构设计决定数据怎样存放和高效访问，例如为常按学号查询的选课记录考虑索引；存储方法、文件组织和索引属于这一层。","逻辑结构设计把概念模型转为关系模式，例如学生(学号,姓名)、课程(课程号,课名)、选课(学号,课程号,成绩)，再明确主键、外键等约束。顺序可复述为：明确需求→画业务联系→形成表与约束→安排存储和访问。","设计之后还要实施并运行维护：按确定的模式创建表、约束和应用，装载并测试数据；投入使用后监测、备份、恢复和按变化调整。完整过程可概括为需求分析→概念结构设计→逻辑结构设计→物理结构设计→实施→运行维护，实际工作可以反馈迭代，不是做完建表就永远结束。"],"boundary":"规模小可以简化文档和过程，但不能等同于“不需要设计”。","id":"y2025q11","sources":[{"year":2025,"q":11,"type":"单选"},{"year":2021,"q":14,"type":"单选","page":3}],"keys":["2025-11","2021-14"],"related":[{"id":"y2020q14","label":"一对一、一对多和多对多联系要双向判断","reason":"E-R概念设计需要由业务规则双向判断一对一、一对多或多对多联系。"},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"从概念模型转成关系模式后，需要明确属性、域、候选码、主键和外键约束。"},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"设计确定或调整字段及约束后，ALTER TABLE是修改已有表结构的实现入口之一。"}],"pointGroups":[{"title":"从业务需求到逻辑结构","indices":[0,1,3]},{"title":"落实存储并持续维护","indices":[2,4]}],"pointPresentation":{"0":{"title":"需求分析的业务规则","navigationLabel":"需求分析的业务规则"},"1":{"title":"概念设计与E-R模型","navigationLabel":"概念设计与E-R模型"},"2":{"title":"物理设计的存取组织","navigationLabel":"物理设计的存取组织"},"3":{"title":"逻辑设计的关系模式","navigationLabel":"逻辑设计的关系模式"},"4":{"title":"实施和运行维护","navigationLabel":"实施和运行维护"}}},{"q":26,"chapter":10,"section":"10.3","type":"多选","topic":"NoSQL与图数据库","title":"NoSQL按数据模型与访问需求选型","trigger":"真题从模型灵活性、查询语言、一致性取舍和社交关系网络选择考查NoSQL。","conclusion":"NoSQL常强调灵活模型与横向扩展；不同产品在一致性、可用性和扩展性间取舍，图数据库则适合多跳关联和路径分析。","points":["常见类型包括键值、文档、列族和图数据库。","NoSQL没有一套所有产品统一采用的标准查询语言。","选型还要评估事务、查询模式、数据结构和运维成本。","宽列/列族数据库是常见NoSQL模型之一；关系数据库也可采用列式存储，不能见到“按列存储”就断言一定是NoSQL。","模型灵活、水平扩展与大规模存储是许多NoSQL产品的适用方向；复杂查询能力、事务和一致性保证必须按具体产品判断，不是所有NoSQL都弱或都强。","键值模型以键定位对应值，适合按标识快速读写的缓存或会话数据；文档模型保存带字段的文档，适合字段结构可变化的对象资料。","列族模型按行键组织数据并按列族管理相关列，适合按预先设计的访问模式处理大规模稀疏数据；它与关系数据库的列式分析存储不是同一概念。","图模型把实体与关系作为节点和边，适合社交关系、多跳推荐和路径分析；“数据量大”本身不足以决定必须使用图数据库。","教学选择流程：先写出常用查询，再看记录结构、关系深度与更新方式，最后比较一致性、事务、扩展和运维要求。","考试常把NoSQL称为非关系型数据库，常见解释是Not Only SQL，强调关系模型之外的多类数据组织方式，不表示完全拒绝SQL。半结构化或非结构化数据是常见选型场景，但不表示关系数据库只能保存简单数字，也不表示所有NoSQL只存非结构化数据；仍要看模型与产品。","以具体模型核对边界：HBase是行键、列族及稀疏数据组织的典型例子；MongoDB的灵活文档仍可设置验证规则；在属性图模型中，节点和边还可带属性，如“关注”边的建立时间。产品例子帮助理解结构，不代表所有同类产品具有完全相同的约束、语言和性能。"],"boundary":"NoSQL不是“不查询”或“永远不要一致性”，图数据库也不是所有大数据场景的默认答案。","id":"y2026q12","sources":[{"year":2023,"q":26,"type":"多选"},{"year":2024,"q":15,"type":"单选"},{"year":2026,"q":12,"type":"单选"},{"year":2022,"q":35,"type":"判断"},{"year":2021,"q":27,"type":"多选","page":5}],"keys":["2023-26","2024-15","2026-12","2022-35","2021-27"],"related":[{"id":"y2025q18","label":"大数据的规模、速度、多样性与价值密度要按材料判断","reason":"数据的规模、速度和类型可解释选型需求，但仍要具体评估查询、事务、一致性和运维成本。"},{"id":"y2020q13","label":"数据库、DBMS与数据库系统不是同一层级","reason":"先区分数据集合、管理软件与整个数据库系统，再讨论关系和NoSQL产品适合什么数据模型。"}],"pointGroups":[{"title":"先识别非关系模型和数据形态","indices":[9,0,1,3]},{"title":"按访问任务理解四类模型","indices":[5,6,7,10]},{"title":"再作选型判断","indices":[2,4,8]}],"pointPresentation":{"0":{"title":"四类常见NoSQL模型","navigationLabel":"四类常见NoSQL模型"},"1":{"title":"查询语言不统一","navigationLabel":"查询语言不统一"},"2":{"title":"选型还看事务和运维","navigationLabel":"选型还看事务和运维"},"3":{"title":"列族与关系列式存储","navigationLabel":"列族与关系列式存储"},"4":{"title":"产品能力须分别判断","navigationLabel":"产品能力须分别判断"},"5":{"title":"键值和文档的访问方式","navigationLabel":"键值和文档的访问方式"},"6":{"title":"列族与稀疏数据","navigationLabel":"列族与稀疏数据"},"7":{"title":"图模型与路径查询","navigationLabel":"图模型与路径查询"},"8":{"title":"从查询出发的选型流程","navigationLabel":"从查询出发的选型流程"},"9":{"title":"NoSQL称谓与结构化边界","navigationLabel":"NoSQL称谓与结构化边界"},"10":{"title":"产品例子和属性图","navigationLabel":"产品例子和属性图"}},"searchAliases":["非关系型数据库 Not Only SQL","半结构化 非结构化 列族 宽列"]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
